739→<!-- Redirect links and searches when in dual view mode -->
740→<script>
741→document.addEventListener("DOMContentLoaded", function () {
742→  if (!window.location.pathname.startsWith("/dual")) return;
743→
744→  function getTargetPanel() {
745→    const selected = document.querySelector('input[name="targetPanel"]:checked');
746→    return selected ? selected.value : "left";
747→  }
748→
749→  function loadInPanel(panel, path) {
750→    if (!path) return;
751→    const iframe = document.getElementById(`iframe-${panel}`);
752→    if (!iframe) return;
753→    const url = path.includes("?") ? path + "&embed=1" : path + "?embed=1";
754→    iframe.src = url;
755→    const inputBox = document.querySelector(`#panel-${panel} input`);
756→    if (inputBox) inputBox.value = path;
757→    console.log(`Loaded "${url}" into panel "${panel}"`);
758→  }
759→  
760→  document.querySelectorAll(".dual-aware a[href^='/'], a.dual-aware[href^='/']").forEach(link => {
761→    link.addEventListener("click", function (e) {
762→      e.preventDefault();
763→      const path = this.getAttribute("href");
764→      loadInPanel(getTargetPanel(), path);
765→    });
766→  });
767→
768→  const idForm = document.getElementById("idsearchForm");
769→  if (idForm) {
770→    idForm.addEventListener("submit", function (e) {
771→      e.preventDefault();
772→      const input = idForm.querySelector(".idsearchTerm").value.trim();
773→      if (!input) return;
774→
775→      let path = null;
776→
777→      if (/^\d+$/.test(input)) {
778→        path = "/go_to/" + encodeURIComponent(input);
779→      } else if (/^((\d+|end)(-(\d+|end))?\s*)+(open|solved|yes|no)?$/i.test(input)) {
780→        const parts = input.split(/\s+/).filter(Boolean);
781→        path = "/range/" + parts.map(encodeURIComponent).join("/");
782→      } else {
783→        alert("Invalid input format.");
784→        return;
785→      }
786→
787→      loadInPanel(getTargetPanel(), path);
788→    });
789→  }
790→
791→  const searchForm = document.getElementById("searchForm");
792→  if (searchForm) {
793→    searchForm.addEventListener("submit", function (e) {
794→      e.preventDefault();
795→      const input = searchForm.querySelector(".searchTerm").value.trim();
796→      if (!input) return;
797→
798→      const path = "/search/" + encodeURIComponent(input);
799→      loadInPanel(getTargetPanel(), path);
800→    });
801→  }
802→});
803→</script>
